    "description": "Durable key-value notes on the verb's own checkpoint chain, plus an atomic single-use nonce guard (action=seen) for replay protection at the public door.",
    "dockerfile": "FROM mshkn-base\nRUN mkdir -p /verb && printf '%s\\n' \\\n'#!/bin/sh' \\\n'set -eu' \\\n'a=\"${1:-}\"; k=\"${2:-}\"; v=\"${3:-}\"' \\\n'R=/state' \\\n'mkdir -p \"$R/notes\" \"$R/seen\"' \\\n'san() { printf \"%s\" \"$1\" | tr -c \"A-Za-z0-9._-\" \"_\"; }' \\\n'need_key() { [ -n \"$k\" ] || { echo \"key required\" >&2; exit 2; }; }' \\\n'case \"$a\" in' \\\n'put) need_key; f=\"$R/notes/$(san \"$k\")\"; printf \"%s\\\\n\" \"$v\" > \"$f\"; echo \"ok put $(san \"$k\")\";;' \\\n'append) need_key; f=\"$R/notes/$(san \"$k\")\"; printf \"%s\\\\n\" \"$v\" >> \"$f\"; echo \"ok append $(san \"$k\")\";;' \\\n'get) need_key; f=\"$R/notes/$(san \"$k\")\"; [ -f \"$f\" ] || { echo \"no such note\" >&2; exit 3; }; cat \"$f\";;' \\\n'list) ls -1 \"$R/notes\" 2>/dev/null || true;;' \\\n'del) need_key; f=\"$R/notes/$(san \"$k\")\"; rm -f \"$f\"; echo \"ok del $(san \"$k\")\";;' \\\n'seen) need_key; f=\"$R/seen/$(san \"$k\")\"; if [ -e \"$f\" ]; then echo \"replay\" >&2; exit 4; fi; date -u +%Y-%m-%dT%H:%M:%SZ > \"$f\"; echo \"fresh\";;' \\\n'selftest) s=0' \\\n'  \"$0\" put t1 hello > /dev/null || s=1' \\\n'  o=$(\"$0\" get t1) || s=1' \\\n'  [ \"$o\" = hello ] || { echo \"FAIL get roundtrip\" >&2; s=1; }' \\\n'  \"$0\" append t1 world > /dev/null || s=1' \\\n'  o=$(\"$0\" get t1 | tr \"\\\\n\" \",\") || s=1' \\\n'  [ \"$o\" = \"hello,world,\" ] || { echo \"FAIL append: $o\" >&2; s=1; }' \\\n'  echo \"keys: $(\"$0\" list | tr \"\\\\n\" \" \")\"' \\\n'  if \"$0\" get nope 2> /dev/null; then echo \"FAIL missing note read\" >&2; s=1; fi' \\\n'  \"$0\" seen n1 > /dev/null || { echo \"FAIL first nonce\" >&2; s=1; }' \\\n'  if \"$0\" seen n1 2> /dev/null; then echo \"FAIL nonce replay accepted\" >&2; s=1; fi' \\\n'  o=$(\"$0\" put \"../../etc/passwd\" pwned) || s=1' \\\n'  echo \"traversal -> $o\"' \\\n'  [ -f /etc/passwd ] || { echo \"FAIL clobbered passwd\" >&2; s=1; }' \\\n'  if \"$0\" put \"\" x 2> /dev/null; then echo \"FAIL empty key accepted\" >&2; s=1; fi' \\\n'  \"$0\" del t1 > /dev/null || s=1' \\\n'  if \"$0\" get t1 2> /dev/null; then echo \"FAIL read after del\" >&2; s=1; fi' \\\n'  echo \"selftest exit=$s\"; exit $s;;' \\\n'*) echo \"unknown action: $a\" >&2; exit 2;;' \\\n'esac' \\\n> /verb/run.sh && chmod +x /verb/run.sh\n",
